# Generated by runa via A2A Mesh delegation
"""
Load-alapú dispatch: Morzsa load 12.6
A health scorer vegye be a load/RAM-ot a score-ba,
a router túlterhelt node-ot kerülje.

Ez a modul implementálja:
  - NodeHealthScorer: CPU load + RAM használat alapú health score számítás
  - LoadAwareRouter: task dispatch túlterhelt node-ok kihagyásával
  - LoadMonitor: valós idejű rendszerterhelés mérése (psutil vagy /proc fallback)
"""

import os
import sys
import time
import json
import socket
import threading
import logging
from dataclasses import dataclass, field, asdict
from typing import Dict, List, Optional, Tuple
from enum import Enum

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] [runa:load_dispatch] %(message)s",
)
logger = logging.getLogger("runa.load_dispatch")

# ---------------------------------------------------------------------------
# Optional psutil import with fallback
# ---------------------------------------------------------------------------
try:
    import psutil
    HAS_PSUTIL = True
except ImportError:
    HAS_PSUTIL = False
    logger.warning("psutil not available — falling back to /proc based metrics")


# ---------------------------------------------------------------------------
# Data structures
# ---------------------------------------------------------------------------
class NodeStatus(Enum):
    HEALTHY = "healthy"
    DEGRADED = "degraded"
    OVERLOADED = "overloaded"
    OFFLINE = "offline"


@dataclass
class NodeLoad:
    """Represents the current load metrics of a node."""
    node_id: str
    cpu_percent: float = 0.0
    ram_percent: float = 0.0
    load_avg_1m: float = 0.0
    load_avg_5m: float = 0.0
    load_avg_15m: float = 0.0
    ram_total_mb: float = 0.0
    ram_used_mb: float = 0.0
    active_tasks: int = 0
    max_tasks: int = 10
    timestamp: float = field(default_factory=time.time)

    @property
    def load_ratio(self) -> float:
        """Normalized load ratio: load_avg_1m / cpu_count (1.0 = fully loaded)."""
        cpu_count = os.cpu_count() or 1
        return min(self.load_avg_1m / cpu_count, 4.0)

    @property
    def task_ratio(self) -> float:
        """Ratio of active tasks to max tasks."""
        if self.max_tasks <= 0:
            return 1.0
        return min(self.active_tasks / self.max_tasks, 1.0)


@dataclass
class HealthScore:
    """Health score result for a node."""
    node_id: str
    score: float  # 0.0 (worst) — 100.0 (best)
    status: NodeStatus
    components: Dict[str, float] = field(default_factory=dict)
    recommendation: str = ""

    def to_dict(self) -> dict:
        d = asdict(self)
        d["status"] = self.status.value
        return d


# ---------------------------------------------------------------------------
# Load Monitor — collects real system metrics
# ---------------------------------------------------------------------------
class LoadMonitor:
    """Collects system load metrics either via psutil or /proc fallback."""

    def __init__(self, node_id: Optional[str] = None):
        self.node_id = node_id or self._default_node_id()

    @staticmethod
    def _default_node_id() -> str:
        hostname = socket.gethostname()
        pid = os.getpid()
        return f"{hostname}:{pid}"

    def collect(self) -> NodeLoad:
        """Collect current load metrics for this node."""
        if HAS_PSUTIL:
            return self._collect_psutil()
        return self._collect_proc()

    def _collect_psutil(self) -> NodeLoad:
        vm = psutil.virtual_memory()
        load1, load5, load15 = os.getloadavg()
        # Count active tasks: approximate with thread count of current process
        try:
            proc = psutil.Process()
            active = proc.num_threads()
        except Exception:
            active = threading.active_count()

        return NodeLoad(
            node_id=self.node_id,
            cpu_percent=psutil.cpu_percent(interval=0.5),
            ram_percent=vm.percent,
            load_avg_1m=load1,
            load_avg_5m=load5,
            load_avg_15m=load15,
            ram_total_mb=vm.total / (1024 * 1024),
            ram_used_mb=vm.used / (1024 * 1024),
            active_tasks=active,
        )

    def _collect_proc(self) -> NodeLoad:
        """Fallback: read /proc/loadavg and /proc/meminfo."""
        load1 = load5 = load15 = 0.0
        try:
            with open("/proc/loadavg", "r") as f:
                parts = f.read().split()
                load1, load5, load15 = float(parts[0]), float(parts[1]), float(parts[2])
        except (FileNotFoundError, IndexError, ValueError):
            pass

        ram_total = ram_used = 0.0
        ram_percent = 0.0
        try:
            with open("/proc/meminfo", "r") as f:
                meminfo = {}
                for line in f:
                    key, _, rest = line.partition(":")
                    meminfo[key.strip()] = rest.strip().split()[0]
                ram_total = int(meminfo.get("MemTotal", "0")) * 1024
                ram_available = int(meminfo.get("MemAvailable", meminfo.get("MemFree", "0"))) * 1024
                ram_used = ram_total - ram_available
                if ram_total > 0:
                    ram_percent = (ram_used / ram_total) * 100.0
        except (FileNotFoundError, IndexError, ValueError):
            pass

        # CPU percent approximation from /proc/stat
        cpu_percent = self._cpu_percent_from_proc()

        return NodeLoad(
            node_id=self.node_id,
            cpu_percent=cpu_percent,
            ram_percent=ram_percent,
            load_avg_1m=load1,
            load_avg_5m=load5,
            load_avg_15m=load15,
            ram_total_mb=ram_total / (1024 * 1024),
            ram_used_mb=ram_used / (1024 * 1024),
            active_tasks=threading.active_count(),
        )

    @staticmethod
    def _cpu_percent_from_proc() -> float:
        """Quick CPU usage estimate from /proc/stat (single sample)."""
        try:
            with open("/proc/stat", "r") as f:
                line = f.readline()
                parts = line.split()[1:]
                values = [int(v) for v in parts]
                idle = values[3]
                total = sum(values)
                if total == 0:
                    return 0.0
                return (1.0 - idle / total) * 100.0
        except (FileNotFoundError, IndexError, ValueError):
            return 0.0


# ---------------------------------------------------------------------------
# Health Scorer — incorporates load + RAM into the score
# ---------------------------------------------------------------------------
class NodeHealthScorer:
    """
    Calculates a composite health score (0–100) that incorporates:
      - CPU load (load_avg_1m normalized by CPU count)
      - RAM usage percentage
      - CPU percent (instantaneous)
      - Task saturation (active_tasks / max_tasks)

    Weights are configurable. Lower load/RAM → higher score.
    Overloaded nodes get a score below the overload threshold and are
    flagged as OVERLOADED so the router can skip them.
    """

    DEFAULT_WEIGHTS = {
        "load_ratio": 0.35,   # load_avg / cpu_count
        "ram_percent": 0.25,  # RAM usage %
        "cpu_percent": 0.20,  # instantaneous CPU %
        "task_ratio": 0.20,   # active/max tasks
    }

    # Thresholds
    OVERLOAD_SCORE_THRESHOLD = 40.0   # below this → OVERLOADED
    DEGRADED_SCORE_THRESHOLD = 65.0   # below this → DEGRADED
    # Hard limits that force OVERLOADED regardless of composite score
    RAM_HARD_LIMIT = 90.0             # % RAM
    LOAD_HARD_LIMIT = 2.0             # load_ratio (2× CPU count)

    def __init__(
        self,
        weights: Optional[Dict[str, float]] = None,
        overload_threshold: float = OVERLOAD_SCORE_THRESHOLD,
        degraded_threshold: float = DEGRADED_SCORE_THRESHOLD,
        ram_hard_limit: float = RAM_HARD_LIMIT,
        load_hard_limit: float = LOAD_HARD_LIMIT,
    ):
        self.weights = {**self.DEFAULT_WEIGHTS, **(weights or {})}
        self.overload_threshold = overload_threshold
        self.degraded_threshold = degraded_threshold
        self.ram_hard_limit = ram_hard_limit
        self.load_hard_limit = load_hard_limit

    def score(self, load: NodeLoad) -> HealthScore:
        """
        Compute health score.

        Each component is normalized to a 0–100 sub-score where 100 = ideal
        (no load) and 0 = fully saturated. The weighted sum gives the final
        composite score.
        """
        components: Dict[str, float] = {}

        # --- Load ratio sub-score ---
        # load_ratio of 0 → 100, load_ratio of 1 → ~50, load_ratio of 2+ → ~0
        lr = load.load_ratio
        load_sub = max(0.0, 100.0 * (1.0 - lr / 2.0))
        components["load_ratio"] = load_sub

        # --- RAM percent sub-score ---
        # 0% RAM → 100, 100% RAM → 0
        ram_sub = max(0.0, 100.0 - load.ram_percent)
        components["ram_percent"] = ram_sub

        # --- CPU percent sub-score ---
        cpu_sub = max(0.0, 100.0 - load.cpu_percent)
        components["cpu_percent"] = cpu_sub

        # --- Task ratio sub-score ---
        task_sub = max(0.0, 100.0 * (1.0 - load.task_ratio))
        components["task_ratio"] = task_sub

        # --- Weighted composite ---
        composite = sum(
            components.get(k, 0.0) * w for k, w in self.weights.items()
        )
        composite = max(0.0, min(100.0, composite))

        # --- Hard limits override ---
        forced_overload = (
            load.ram_percent >= self.ram_hard_limit
            or lr >= self.load_hard_limit
        )

        # --- Determine status ---
        if forced_overload or composite < self.overload_threshold:
            status = NodeStatus.OVERLOADED
            recommendation = (
                f"Node {load.node_id} overloaded "
                f"(load_ratio={lr:.2f}, ram={load.ram_percent:.1f}%, "
                f"cpu={load.cpu_percent:.1f}%). Skip for new dispatch."
            )
        elif composite < self.degraded_threshold:
            status = NodeStatus.DEGRADED
            recommendation = (
                f"Node {load.node_id} degraded (score={composite:.1f}). "
                f"Dispatch with caution."
            )
        else:
            status = NodeStatus.HEALTHY
            recommendation = f"Node {load.node_id} healthy (score={composite:.1f})."

        return HealthScore(
            node_id=load.node_id,
            score=round(composite, 2),
            status=status,
            components={k: round(v, 2) for k, v in components.items()},
            recommendation=recommendation,
        )


# ---------------------------------------------------------------------------
# Load-Aware Router — dispatches tasks avoiding overloaded nodes
# ---------------------------------------------------------------------------
class LoadAwareRouter:
    """
    Routes tasks to the least-loaded healthy node.

    Strategy:
      1. Exclude OFFLINE and OVERLOADED nodes.
      2. Among remaining nodes, pick the one with the highest health score.
      3. If all nodes are overloaded, pick the least-bad one (fallback) and log
         a warning.
      4. If no nodes are registered, raise RuntimeError.
    """

    def __init__(
        self,
        scorer: Optional[NodeHealthScorer] = None,
        max_retries: int = 3,
        cooldown_seconds: float = 5.0,
    ):
        self.scorer = scorer or NodeHealthScorer()
        self.max_retries = max_retries
        self.cooldown_seconds = cooldown_seconds
        self._nodes: Dict[str, NodeLoad] = {}
        self._scores: Dict[str, HealthScore] = {}
        self._lock = threading.RLock()
        self._overload_cooldowns: Dict[str, float] = {}

    # -- Registration --
    def register_node(self, load: NodeLoad) -> HealthScore:
        """Register or update a node's load data and return its health score."""
        with self._lock:
            self._nodes[load.node_id] = load
            hs = self.scorer.score(load)
            self._scores[load.node_id] = hs
            if hs.status == NodeStatus.OVERLOADED:
                self._overload_cooldowns[load.node_id] = time.time() + self.cooldown_seconds
                logger.warning(hs.recommendation)
            elif hs.status == NodeStatus.DEGRADED:
                logger.info(hs.recommendation)
            else:
                logger.debug(hs.recommendation)
            return hs

    def unregister_node(self, node_id: str) -> None:
        with self._lock:
            self._nodes.pop(node_id, None)
            self._scores.pop(node_id, None)
            self._overload_cooldowns.pop(node_id, None)

    def get_all_scores(self) -> Dict[str, HealthScore]:
        with self._lock:
            return dict(self._scores)

    # -- Dispatch --
    def select_node(self, exclude: Optional[List[str]] = None) -> Tuple[str, HealthScore]:
        """
        Select the best node for a new task.
        Returns (node_id, health_score).
        Raises RuntimeError if no nodes available.
        """
        exclude = exclude or []
        now = time.time()

        with self._lock:
            available: List[Tuple[str, HealthScore]] = []
            overloaded_fallback: List[Tuple[str, HealthScore]] = []

            for node_id, hs in self._scores.items():
                if node_id in exclude:
                    continue

                # Check cooldown for recently overloaded nodes
                cooldown_until = self._overload_cooldowns.get(node_id)
                if cooldown_until and now < cooldown_until:
                    logger.debug(
                        f"Node {node_id} in overload cooldown "
                        f"({cooldown_until - now:.1f}s remaining)"
                    )
                    overloaded_fallback.append((node_id, hs))
                    continue

                if hs.status in (NodeStatus.HEALTHY, NodeStatus.DEGRADED):
                    available.append((node_id, hs))
                elif hs.status == NodeStatus.OVERLOADED:
                    overloaded_fallback.append((node_id, hs))

            if available:
                # Sort by score descending — best node first
                available.sort(key=lambda x: x[1].score, reverse=True)
                best_id, best_hs = available[0]
                logger.info(
                    f"Dispatch selected {best_id} "
                    f"(score={best_hs.score:.1f}, status={best_hs.status.value})"
                )
                return best_id, best_hs

            if overloaded_fallback:
                # All nodes overloaded — pick least bad
                overloaded_fallback.sort(key=lambda x: x[1].score, reverse=True)
                best_id, best_hs = overloaded_fallback[0]
                logger.warning(
                    f"All nodes overloaded! Fallback dispatch to {best_id} "
                    f"(score={best_hs.score:.1f})"
                )
                return best_id, best_hs

            raise RuntimeError("No nodes available for dispatch")

    def dispatch(self, task_id: str, task_payload: Optional[dict] = None,
                 exclude: Optional[List[str]] = None) -> dict:
        """
        Dispatch a task to the best available node.
        Returns a dispatch result dict.
        """
        task_payload = task_payload or {}
        attempts = 0
        tried: List[str] = list(exclude or [])

        while attempts < self.max_retries:
            attempts += 1
            try:
                node_id, hs = self.select_node(exclude=tried)
                result = {
                    "task_id": task_id,
                    "node_id": node_id,
                    "health_score": hs.score,
                    "node_status": hs.status.value,
                    "attempt": attempts,
                    "payload": task_payload,
                    "dispatched_at": time.time(),
                    "success": True,
                }
                logger.info(
                    f"Task {task_id} dispatched to {node_id} "
                    f"(attempt {attempts}, score={hs.score:.1f})"
                )
                return result
            except RuntimeError:
                logger.error(f"No nodes available for task {task_id} (attempt {attempts})")
                if attempts >= self.max_retries:
                    return {
                        "task_id": task_id,
                        "node_id": None,
                        "health_score": 0.0,
                        "node_status": "no_node",
                        "attempt": attempts,
                        "payload": task_payload,
                        "dispatched_at": time.time(),
                        "success": False,
                        "error": "No nodes available after retries",
                    }
                time.sleep(0.5 * attempts)

        # Should not reach here, but safety net
        return {
            "task_id": task_id,
            "node_id": None,
            "health_score": 0.0,
            "node_status": "failed",
            "attempt": attempts,
            "payload": task_payload,
            "dispatched_at": time.time(),
            "success": False,
            "error": "Unexpected dispatch failure",
        }


# ---------------------------------------------------------------------------
# Mesh Node Registry — simulates multiple nodes for demonstration
# ---------------------------------------------------------------------------
class MeshNodeRegistry:
    """
    Simulates a mesh of nodes. In production this would be backed by
    a shared registry (Redis, etcd, or the A2A mesh gossip protocol).
    Here we use an in-memory dict with a background thread that periodically
    collects local metrics and allows injecting synthetic load for other nodes.
    """

    def __init__(self, router: LoadAwareRouter, local_monitor: LoadMonitor):
        self.router = router
        self.local_monitor = local_monitor
        self._running = False
        self._thread: Optional[threading.Thread] = None
        self._synthetic_nodes: Dict[str, NodeLoad] = {}

    def add_synthetic_node(self, load: NodeLoad) -> None:
        """Add a simulated remote node with given load metrics."""
        self._synthetic_nodes[load.node_id] = load
        self.router.register_node(load)
        logger.info(f"Registered synthetic node {load.node_id}")

    def update_synthetic_node(self, node_id: str, **kwargs) -> None:
        """Update a synthetic node's load metrics."""
        if node_id in self._synthetic_nodes:
            load = self._synthetic_nodes[node_id]
            for k, v in kwargs.items():
                if hasattr(load, k):
                    setattr(load, k, v)
            load.timestamp = time.time()
            self.router.register_node(load)

    def start(self, interval: float = 5.0) -> None:
        """Start background monitoring of the local node."""
        self._running = True
        self._thread = threading.Thread(
            target=self._monitor_loop, args=(interval,), daemon=True
        )
        self._thread.start()
        logger.info(f"Started node monitoring (interval={interval}s)")

    def stop(self) -> None:
        self._running = False
        if self._thread:
            self._thread.join(timeout=2.0)
        logger.info("Stopped node monitoring")

    def _monitor_loop(self, interval: float) -> None:
        while self._running:
            try:
                load = self.local_monitor.collect()
                self.router.register_node(load)
            except Exception as e:
                logger.error(f"Monitor error: {e}")
            time.sleep(interval)


# ---------------------------------------------------------------------------
# Demo / CLI entry point
# ---------------------------------------------------------------------------
def print_separator(title: str = "") -> None:
    line = "=" * 70
    if title:
        print(f"\n{line}\n  {title}\n{line}")
    else:
        print(line)


def run_demo() -> None:
    """Demonstrate load-aware dispatch with multiple simulated nodes."""
    print_separator("A2A Mesh — Load-alapú dispatch (Morzsa load 12.6)")
    print("  Health scorer: load + RAM + CPU + task saturation → composite score")
    print("  Router: skips OVERLOADED nodes, picks highest-score healthy node\n")

    # --- Setup ---
    scorer = NodeHealthScorer()
    router = LoadAwareRouter(scorer=scorer, max_retries=3, cooldown_seconds=3.0)
    local_monitor = LoadMonitor(node_id="morzsa-local")
    registry = MeshNodeRegistry(router, local_monitor)

    # --- Register nodes with varying load levels ---
    nodes = [
        NodeLoad(
            node_id="morzsa-01",
            cpu_percent=15.0, ram_percent=40.0,
            load_avg_1m=0.8, load_avg_5m=0.6, load_avg_15m=0.5,
            ram_total_mb=8192, ram_used_mb=3277,
            active_tasks=2, max_tasks=10,
        ),
        NodeLoad(
            node_id="morzsa-02",
            cpu_percent=85.0, ram_percent=88.0,
            load_avg_1m=12.6, load_avg_5m=10.2, load_avg_15m=8.1,
            ram_total_mb=8192, ram_used_mb=7209,
            active_tasks=9, max_tasks=10,
        ),
        NodeLoad(
            node_id="morzsa-03",
            cpu_percent=45.0, ram_percent=62.0,
            load_avg_1m=2.1, load_avg_5m=1.8, load_avg_15m=1.5,
            ram_total_mb=16384, ram_used_mb=10158,
            active_tasks=5, max_tasks=10,
        ),
        NodeLoad(
            node_id="morzsa-04",
            cpu_percent=95.0, ram_percent=93.0,
            load_avg_1m=15.3, load_avg_5m=12.0, load_avg_15m=9.5,
            ram_total_mb=4096, ram_used_mb=3809,
            active_tasks=10, max_tasks=10,
        ),
        NodeLoad(
            node_id="morzsa-05",
            cpu_percent=30.0, ram_percent=55.0,
            load_avg_1m=1.2, load_avg_5m=1.0, load_avg_15m=0.9,
            ram_total_mb=8192, ram_used_mb=4506,
            active_tasks=3, max_tasks=10,
        ),
    ]

    print_separator("Node Registration & Health Scores")
    for n in nodes:
        hs = router.register_node(n)
        print(f"\n  Node: {hs.node_id}")
        print(f"    Score: {hs.score:.1f}/100  Status: {hs.status.value.upper()}")
        print(f"    Components:")
        for comp, val in hs.components.items():
            print(f"      {comp:15s}: {val:.1f}")
        print(f"    → {hs.recommendation}")

    # --- Dispatch tasks ---
    print_separator("Task Dispatch Demo")
    tasks = [
        ("task-001", {"type": "embedding", "size": "small"}),
        ("task-002", {"type": "inference", "size": "medium"}),
        ("task-003", {"type": "training", "size": "large"}),
        ("task-004", {"type": "embedding", "size": "small"}),
        ("task-005", {"type": "inference", "size": "medium"}),
    ]

    for task_id, payload in tasks:
        result = router.dispatch(task_id, payload)
        status = "✓" if result["success"] else "✗"
        print(
            f"  {status} {result['task_id']} → {result['node_id']} "
            f"(score={result['health_score']:.1f}, "
            f"status={result['node_status']}, "
            f"attempt={result['attempt']})"
        )

    # --- Show that overloaded nodes are skipped ---
    print_separator("Overload Avoidance Verification")
    scores = router.get_all_scores()
    overloaded = [
        nid for nid, hs in scores.items()
        if hs.status == NodeStatus.OVERLOADED
    ]
    healthy = [
        nid for nid, hs in scores.items()
        if hs.status == NodeStatus.HEALTHY
    ]
    degraded = [
        nid for nid, hs in scores.items()
        if hs.status == NodeStatus.DEGRADED
    ]
    print(f"  Healthy nodes:   {healthy or 'none'}")
    print(f"  Degraded nodes:  {degraded or 'none'}")
    print(f"  Overloaded nodes:{overloaded or 'none'}")
    print(f"  → Router skips: {overloaded}")

    # --- Simulate all nodes becoming overloaded ---
    print_separator("Fallback: All Nodes Overloaded")
    for nid in ["morzsa-01", "morzsa-03", "morzsa-05"]:
        registry.update_synthetic_node(
            nid,
            cpu_percent=92.0,
            ram_percent=91.0,
            load_avg_1m=14.0,
            active_tasks=10,
        )
    # Re-register the already-overloaded nodes to refresh
    for nid in ["morzsa-02", "morzsa-04"]:
        registry.update_synthetic_node(
            nid,
            cpu_percent=96.0,
            ram_percent=95.0,
            load_avg_1m=16.0,
            active_tasks=10,
        )

    print("\n  Updated scores:")
    for nid, hs in router.get_all_scores().items():
        print(f"    {nid}: score={hs.score:.1f} status={hs.status.value}")

    result = router.dispatch("task-emergency", {"type": "critical", "size": "small"})
    status = "✓" if result["success"] else "✗"
    print(
        f"\n  {status} {result['task_id']} → {result['node_id']} "
        f"(score={result['health_score']:.1f}, "
        f"status={result['node_status']})"
    )
    if result["success"]:
        print("  → Fallback to least-overloaded node (all were overloaded)")

    # --- JSON export of current state ---
    print_separator("Current State (JSON)")
    state = {
        "nodes": {
            nid: hs.to_dict()
            for nid, hs in router.get_all_scores().items()
        },
        "timestamp": time.time(),
    }
    print(json.dumps(state, indent=2))

    print_separator("Demo Complete")


def run_local_check() -> None:
    """Quick single-node check: collect local metrics and show health score."""
    print_separator("Local Node Health Check")
    monitor = LoadMonitor()
    scorer = NodeHealthScorer()

    print(f"  Node ID: {monitor.node_id}")
    print(f"  psutil available: {HAS_PSUTIL}")

    load = monitor.collect()
    print(f"\n  Collected metrics:")
    print(f"    CPU percent:     {load.cpu_percent:.1f}%")
    print(f"    RAM percent:     {load.ram_percent:.1f}%")
    print(f"    RAM used/total:  {load.ram_used_mb:.0f}MB / {load.ram_total_mb:.0f}MB")
    print(f"    Load avg (1m):   {load.load_avg_1m:.2f}")
    print(f"    Load avg (5m):   {load.load_avg_5m:.2f}")
    print(f"    Load avg (15m):  {load.load_avg_15m:.2f}")
    print(f"    Load ratio:      {load.load_ratio:.2f}")
    print(f"    Active tasks:    {load.active_tasks}/{load.max_tasks}")

    hs = scorer.score(load)
    print(f"\n  Health Score: {hs.score:.1f}/100  ({hs.status.value.upper()})")
    print(f"  Components:")
    for comp, val in hs.components.items():
        print(f"    {comp:15s}: {val:.1f}")
    print(f"\n  → {hs.recommendation}")
    print_separator()


