# Main
# ---------------------------------------------------------------------------
if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] == "--local":
        run_local_check()
    elif len(sys.argv) > 1 and sys.argv[1] == "--demo":
        run_demo()
    else:
        print("A2A Mesh — Load-alapú dispatch (Morzsa load 12.6)")
        print()
        print("Usage:")
        print("  python load_dispatch.py --local   Check local node health")
        print("  python load_dispatch.py --demo    Run multi-node dispatch demo")
        print()
        print("Running local check by default...\n")
        run_local_check()